def transform(grid):
    out = [row[:] for row in grid]

    # The pattern on the left is used to set the heights of four columns
    # in the chamber on the right.
    left_cols = (1, 3, 5, 7)
    right_cols = (11, 13, 15, 17)

    for r in range(len(out)):
        for c in range(9):
            out[r][c] = 0

    for left_col, right_col in zip(left_cols, right_cols):
        height = 0
        for r in range(5, 0, -1):
            if grid[r][left_col] == 5:
                height += 1
            else:
                break

        # Keep the colored cells in their original order.
        colors = [
            grid[r][right_col]
            for r in range(1, 5)
            if grid[r][right_col] not in (0, 5)
        ]

        # Clear the old colored cells, leaving any background 5s in place.
        for r in range(1, 5):
            if out[r][right_col] != 5:
                out[r][right_col] = 0

        capacity = 5 - height

        # Add the profile beneath the open space.
        for r in range(6 - height, 6):
            out[r][right_col] = 5

        # The colored cells settle at the bottom of the available space.
        count = min(len(colors), capacity)
        if count:
            survivors = colors[-count:]
            first_row = capacity - count + 1
            for i, color in enumerate(survivors):
                out[first_row + i][right_col] = color

    # Recreate the horizontal base.
    for c in range(11, 18):
        out[5][c] = 5

    return out
